const item = $input.first();
const body = item.json.body || {};
let text = (body.text ?? '').toString();
let source_url = (body.source_url ?? body.sourceUrl ?? '').toString().trim();

/**
 * Shared text cleanup for kb-capture (Jina vacuum + OCR).
 * Used by unit tests; inlined into Prepare Capture Code node.
 */
function cleanExtractedText(raw) {
  if (raw == null) return '';
  let s = String(raw);
  if (!s.trim()) return '';

  // 1) script/style out entirely
  s = s.replace(/<script\b[\s\S]*?<\/script>/gi, ' ');
  s = s.replace(/<style\b[\s\S]*?<\/style>/gi, ' ');
  s = s.replace(/<noscript\b[\s\S]*?<\/noscript>/gi, ' ');

  // 2) unwrap strikethrough HTML (keep inner text)
  s = s.replace(/<(?:s|strike|del)\b[^>]*>([\s\S]*?)<\/(?:s|strike|del)>/gi, '$1');
  s = s.replace(/<\/?(?:s|strike|del)\b[^>]*>/gi, '');

  // 3) strip remaining HTML tags, keep text
  s = s.replace(/<!--[\s\S]*?-->/g, ' ');
  s = s.replace(/<\/?[a-zA-Z][^>]*>/g, ' ');

  // 4) markdown strikethrough ~~...~~ → keep text
  s = s.replace(/~~([^~\n]{0,400})~~/g, '$1');

  // 5) zero-width / BOM / soft hyphen junk
  s = s.replace(/[\u200B-\u200D\uFEFF\u00AD]/g, '');

  // 6) orphan bracket tags like [/...] leftover from broken markup
  s = s.replace(/\[\/[^\]]{0,60}\]/g, ' ');
  // leftover bare angle fragments that aren't real words
  s = s.replace(/<\/?[a-zA-Z][^>\n]{0,40}>/g, ' ');

  // 7) Jina Reader chrome — prefer body after "Markdown Content:"
  const mdMatch = s.match(/^Markdown Content:\s*/im);
  if (mdMatch && typeof mdMatch.index === 'number') {
    const titleMatch = s.match(/^Title:\s*(.+)$/m);
    const title = titleMatch ? titleMatch[1].trim() : '';
    s = s.slice(mdMatch.index + mdMatch[0].length);
    if (title) {
      const head = s.trim().slice(0, Math.min(60, title.length));
      if (!title.startsWith(head) && !s.trim().startsWith('#')) {
        s = title + '\n\n' + s;
      }
    }
  } else {
    s = s.replace(/^(Title|URL Source|Published Time|Markdown Content):\s*.*$/gim, '');
  }

  const BANNER_PHRASE =
    /accepter (les |tous les )?cookies|accept(\s+all)?\s+cookies|reject\s+all|manage (cookie )?preferences|nous utilisons des cookies|this site uses cookies|privacy center|consent management|cookiebot|onetrust|didomi|politique de confidentialit[eé]|privacy policy|tracking technologies|adchoices|gestion des cookies|param[eè]tres (des |de )?cookies/i;

  const CONSENT_TOKEN =
    /cookies?|consentement|consent|accepter|accept all|reject all|manage preferences|politique de confidentialit[eé]|privacy policy|nous utilisons des cookies|this site uses cookies|\bGDPR\b|\bRGPD\b|OneTrust|Cookiebot|Didomi|consent management|privacy center|tracking technologies|essential cookies|targeted advertising|adchoices|social media services|core website features|gestion des cookies|pr[eé]f[eé]rences/gi;

  const CMP_HEADER =
    /^(Privacy Center|Social Media|Essential|Targeted|Performance|Functional|Marketing|Strictly Necessary|Cookie Settings|Manage Consent|Gestion des cookies|Centre de confidentialit[eé]|Pr[eé]f[eé]rences de cookies)$/i;

  function consentScore(p) {
    const m = p.match(CONSENT_TOKEN);
    return m ? m.length : 0;
  }

  // 8) drop consent-heavy paragraphs (blocks, not every "cookie" mention)
  function isConsentBlock(t) {
    if (!t) return false;
    if (CMP_HEADER.test(t) && t.length < 80) return true;
    if (BANNER_PHRASE.test(t) && t.length < 1200) return true;
    const score = consentScore(t);
    // heavy consent vocabulary → block
    if (score >= 2) return true;
    // short banner-like blurbs with classic consent phrasing
    if (score >= 1 && t.length < 280 && BANNER_PHRASE.test(t)) return true;
    return false;
  }

  let paras = s.split(/\n\s*\n+/);
  paras = paras.filter((p) => !isConsentBlock(p.trim()));

  // drop leading short CMP chrome (headers / toggle rows) at document start
  while (paras.length) {
    const t = paras[0].trim();
    if (!t) {
      paras.shift();
      continue;
    }
    if (CMP_HEADER.test(t)) {
      paras.shift();
      continue;
    }
    if (isConsentBlock(t)) {
      paras.shift();
      continue;
    }
    if (/^(- \[[ xX]\]\s*On\s*)+$/m.test(t)) {
      paras.shift();
      continue;
    }
    break;
  }

  s = paras.join('\n\n');

  // line-level CMP chrome
  s = s
    .split('\n')
    .filter((line) => {
      const t = line.trim();
      if (!t) return true;
      if (/^- \[[ xX]\]\s*On\s*$/.test(t)) return false;
      if (/^\*\s*\*\s*\*$/.test(t) || /^\*{3,}$/.test(t)) return false;
      if (CMP_HEADER.test(t)) return false;
      if (BANNER_PHRASE.test(t) && t.length < 220) return false;
      return true;
    })
    .join('\n');

  // 9) whitespace normalize
  s = s.replace(/[ \t]+/g, ' ');
  s = s.replace(/ *\n */g, '\n');
  s = s.replace(/\n{3,}/g, '\n\n');
  return s.trim();
}

// Avoid `new URL()` — unavailable / unreliable in some n8n Code sandboxes.
if (!/^https?:\/\/[^\s<>"{}|\\^`[\]]+$/i.test(source_url)) {
  source_url = '';
} else {
  source_url = source_url.replace(/[.,);]+$/g, '');
}

const bin = item.binary || {};
let has_image = false;
for (const key of Object.keys(bin)) {
  const b = bin[key];
  if (b && b.mimeType && String(b.mimeType).startsWith('image/')) {
    has_image = true;
    break;
  }
}
if (!has_image) {
  for (const key of Object.keys(bin)) {
    if (bin[key] && bin[key].data) {
      has_image = true;
      break;
    }
  }
}

if (!text && !source_url && !has_image) {
  throw new Error('Need at least one of: text, source_url, or image file');
}

let full_text_raw = '';
let full_text = '';
let vacuum_ok = false;
let vacuum_error = '';
if (source_url) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://r.jina.ai/' + source_url,
      headers: {
        Accept: 'text/plain',
        'User-Agent': 'kb-capture/1.0',
      },
      timeout: 20000,
    });
    full_text_raw = typeof res === 'string' ? res : String(res ?? '');
    full_text = cleanExtractedText(full_text_raw);
    vacuum_ok = full_text.trim().length >= 80;
    if (!vacuum_ok) vacuum_error = 'vacuum_too_short';
  } catch (e) {
    full_text_raw = '';
    full_text = '';
    vacuum_ok = false;
    vacuum_error = (e && e.message) ? String(e.message).slice(0, 200) : 'vacuum_failed';
  }
}

const text_clean = cleanExtractedText(text);

const content_for_llm = (
  vacuum_ok ? full_text : (text_clean || source_url || 'capture sans texte')
).slice(0, 12000);

const body_content = vacuum_ok ? full_text : text_clean;

return [{
  json: {
    text: text_clean,
    text_raw: text,
    source_url,
    has_image,
    full_text,
    full_text_raw,
    full_text_clean: full_text,
    vacuum_ok,
    vacuum_error,
    content_for_llm,
    body_content,
  },
  binary: item.binary,
}];

